def second_largest_distinct(nums):
    unique_nums = sorted(set(nums), reverse=True)
    return unique_nums[1] if len(unique_nums) >= 2 else None

def deduplicate_keep_last(nums):
    seen = set()
    res = []
    for x in reversed(nums):
        if x not in seen:
            seen.add(x)
            res.append(x)
    return res[::-1]

def most_frequent_smallest(nums):
    if not nums:
        return None
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    return min(counts.keys(), key=lambda x: (-counts[x], x))

def chunk_list(lst, n):
    if not lst or n <= 0:
        return []
    return [lst[i:i + n] for i in range(0, len(lst), n)]

def rotate_list(lst, k):
    if not lst:
        return []
    k = k % len(lst)
    return lst[-k:] + lst[:-k] if k else lst[:]

def longest_increasing_run(nums):
    if not nums:
        return 0
    max_len = cur_len = 1
    for i in range(1, len(nums)):
        cur_len = cur_len + 1 if nums[i] > nums[i - 1] else 1
        max_len = max(max_len, cur_len)
    return max_len

def max_pair_product(nums):
    if len(nums) < 2:
        return None
    s = sorted(nums)
    return max(s[0] * s[1], s[-1] * s[-2])

def multiset_intersection(a, b):
    res = []
    for x in sorted(set(a) & set(b)):
        res.extend([x] * min(a.count(x), b.count(x)))
    return res

def run_length_encode_typed(lst):
    res = []
    for x in lst:
        if res and res[-1][0] == x and type(res[-1][0]) is type(x):
            res[-1] = (x, res[-1][1] + 1)
        else:
            res.append((x, 1))
    return res

def invert_dict_sorted(d):
    inv = {}
    for k, v in d.items():
        inv.setdefault(v, []).append(k)
    return {v: sorted(keys) for v, keys in inv.items()}

def merge_and_prune_zero(d1, d2):
    res = dict(d1)
    for k, v in d2.items():
        res[k] = res.get(k, 0) + v
    return {k: v for k, v in res.items() if v != 0}

def majority_k_elements(nums, k):
    if not nums:
        return []
    threshold = len(nums) / k
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    return sorted([x for x, c in counts.items() if c > threshold])

def count_alpha_sorted(s):
    counts = {}
    for ch in s.lower():
        if ch.isalpha():
            counts[ch] = counts.get(ch, 0) + 1
    return sorted(counts.items())

def second_most_frequent(nums):
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    freqs = sorted(set(counts.values()), reverse=True)
    if len(freqs) < 2:
        return None
    return min(k for k, v in counts.items() if v == freqs[1])

def has_unique_frequencies(nums):
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
    return len(counts) == len(set(counts.values()))

def count_target_pairs(nums, target):
    seen = {}
    ans = 0
    for x in nums:
        ans += seen.get(target - x, 0)
        seen[x] = seen.get(x, 0) + 1
    return ans

def multiset_difference(l1, l2):
    counts = {}
    for x in l2:
        counts[x] = counts.get(x, 0) + 1
    res = []
    for x in l1:
        if counts.get(x, 0) > 0:
            counts[x] -= 1
        else:
            res.append(x)
    return res

def average_word_indices(words):
    sums, counts = {}, {}
    for i, w in enumerate(words):
        sums[w] = sums.get(w, 0) + i
        counts[w] = counts.get(w, 0) + 1
    return {w: float(sums[w]) / counts[w] for w in counts}

def merge_non_zero(d1, d2):
    res = {}
    for k in set(d1) | set(d2):
        val = d1.get(k, 0) + d2.get(k, 0)
        if val != 0:
            res[k] = val
    return res

def second_highest_freq(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    freqs = sorted(set(counts.values()), reverse=True)
    return freqs[1] if len(freqs) >= 2 else None

def group_by_modulo(nums, k):
    groups = {}
    for x in nums:
        groups.setdefault(x % k, []).append(x)
    return {r: groups[r] for r in sorted(groups)}

def subtract_frequencies(d1, d2):
    res = {}
    for k, v in d1.items():
        diff = v - d2.get(k, 0)
        if diff > 0:
            res[k] = diff
    return res

def min_value_largest_key(d):
    if not d:
        return None
    return min(d.keys(), key=lambda k: (d[k], -k if isinstance(k, (int, float)) else k)) if all(isinstance(k, (int, float)) for k in d) else max([k for k, v in d.items() if v == min(d.values())])

def unique_last_occurrence(lst):
    seen = set()
    res = []
    for x in reversed(lst):
        if x not in seen:
            seen.add(x)
            res.append(x)
    return res[::-1]

def second_smallest_unique(nums):
    uniq = sorted(set(nums))
    return uniq[1] if len(uniq) >= 2 else None

def common_in_two_of_three(l1, l2, l3):
    s1, s2, s3 = set(l1), set(l2), set(l3)
    res = (s1 & s2) | (s2 & s3) | (s1 & s3)
    return tuple(sorted(res))

def smallest_odd_frequency(nums):
    odds = set()
    for x in nums:
        if x in odds:
            odds.remove(x)
        else:
            odds.add(x)
    return min(odds) if odds else None

def are_elements_strictly_unique(lst):
    typed_items = {(type(x), x) for x in lst}
    return len(typed_items) == len(lst)

def singletons_descending(nums):
    seen = set()
    dups = set()
    for x in nums:
        if x in seen:
            dups.add(x)
        seen.add(x)
    return sorted(seen - dups, reverse=True)

def longest_uniform_sublist(lst):
    if not lst:
        return 0
    max_len = cur_len = 1
    for i in range(1, len(lst)):
        cur_len = cur_len + 1 if lst[i] == lst[i - 1] else 1
        max_len = max(max_len, cur_len)
    return max_len

def exclusive_to_first(first, *others):
    res = set(first)
    for other in others:
        res.difference_update(other)
    return sorted(res)

def count_unique_sum_pairs(nums, target):
    uniq = set(nums)
    pairs = set()
    for x in uniq:
        y = target - x
        if y in uniq and x < y:
            pairs.add((x, y))
    return len(pairs)

def max_unique_chars_string(strings):
    if not strings:
        return None
    return max(strings, key=lambda s: len(set(s.lower())))

def merge_intervals(intervals):
    if not intervals:
        return []
    res = []
    for start, end in sorted(intervals):
        if res and start <= res[-1][1]:
            res[-1] = (res[-1][0], max(res[-1][1], end))
        else:
            res.append((start, end))
    return res

def common_intersection(intervals):
    if not intervals:
        return None
    low = max(i[0] for i in intervals)
    high = min(i[1] for i in intervals)
    return (low, high) if low <= high else None

def count_covered_integers(intervals):
    if not intervals:
        return 0
    merged = []
    for s, e in sorted(intervals):
        if merged and s <= merged[-1][1] + 1:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    return sum(e - s + 1 for s, e in merged)

def longest_interval(intervals):
    if not intervals:
        return None
    best = min(intervals, key=lambda x: (-(x[1] - x[0]), x[0]))
    return (best[0], best[1])

def find_interval_gaps(intervals, bounds):
    b_start, b_end = bounds
    res, curr = [], b_start
    for s, e in sorted(intervals):
        if e < curr or s > b_end:
            continue
        if s > curr:
            res.append((curr, min(s, b_end)))
        curr = max(curr, e)
    if curr < b_end:
        res.append((curr, b_end))
    return res

def compress_to_ranges(nums):
    res = []
    for n in sorted(set(nums)):
        if res and n == res[-1][1] + 1:
            res[-1] = (res[-1][0], n)
        else:
            res.append((n, n))
    return res

def subtract_interval(a, b):
    res = []
    if a[0] < b[0]:
        res.append((a[0], min(a[1], b[0])))
    if a[1] > b[1]:
        res.append((max(a[0], b[1]), a[1]))
    return [r for r in res if r[0] < r[1]] or ([tuple(a)] if a[0] == a[1] and not (b[0] <= a[0] <= b[1]) else [])

def most_overlapped_point(intervals):
    if not intervals:
        return None
    events = []
    for s, e in intervals:
        events.extend([(s, -1), (e, 1)])
    curr = best_c = best_p = 0
    for p, t in sorted(events):
        curr -= t
        if curr > best_c:
            best_c, best_p = curr, p
    return best_p

def are_intervals_disjoint(intervals):
    s = sorted(intervals)
    return all(s[i][1] < s[i+1][0] for i in range(len(s) - 1))

def gen_fib(a, b, n):
    if n <= 0:
        return ()
    res = [a, b]
    for _ in range(2, n):
        res.append(res[-1] + res[-2])
    return tuple(res[:n])

def is_geometric(seq):
    if len(seq) < 2:
        return True
    if seq[0] == 0:
        return all(x == 0 for x in seq[1:])
    return all(seq[i] * seq[0] == seq[i-1] * seq[1] for i in range(1, len(seq)))

def kth_difference(seq, k):
    res = list(seq)
    for _ in range(k):
        if not res:
            break
        res = [res[i+1] - res[i] for i in range(len(res) - 1)]
    return res

def recaman_until_dup(n):
    if n <= 0:
        return []
    seq, seen = [0], {0}
    for i in range(1, n):
        nxt = seq[-1] - i
        if nxt <= 0 or nxt in seen:
            nxt = seq[-1] + i
        seq.append(nxt)
        if nxt in seen:
            break
        seen.add(nxt)
    return seq

def min_period(seq):
    n = len(seq)
    for p in range(1, n + 1):
        if all(seq[i] == seq[i - p] for i in range(p, n)):
            return p
    return 0

def strict_local_maxima(seq):
    peaks = {seq[i] for i in range(1, len(seq) - 1) if seq[i - 1] < seq[i] > seq[i + 1]}
    return sorted(peaks, reverse=True)

def eval_recurrence(a0, a1, c1, c2, n):
    if n >= 0:
        for _ in range(n):
            a0, a1 = a1, c1 * a1 + c2 * a0
        return a0
    if c2 == 0:
        return None
    for _ in range(-n):
        if (a1 - c1 * a0) % c2 == 0:
            a0, a1 = (a1 - c1 * a0) // c2, a0
        else:
            a0, a1 = (a1 - c1 * a0) / c2, a0
    return a0

def interleave_truncate(seq1, seq2):
    res = []
    for x, y in zip(seq1, seq2):
        res.extend((x, y))
    return tuple(res)

def collatz_seq(n):
    if n <= 0:
        return []
    res = [n]
    while n > 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        res.append(n)
    return res

def shift_weekday(day, n):
    if not (1 <= day <= 7):
        return None
    return (day - 1 + n) % 7 + 1

def count_leap_years(a, b):
    if a > b:
        return 0
    def leaps(y):
        return y // 4 - y // 100 + y // 400
    return leaps(b) - leaps(a - 1)

def count_weekday_in_span(start_day, n_days, target_day):
    if n_days <= 0:
        return 0
    offset = (target_day - start_day) % 7
    if offset >= n_days:
        return 0
    return 1 + (n_days - 1 - offset) // 7

def day_of_year_to_md(doy):
    if not (1 <= doy <= 365):
        return None
    days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    for m, d in enumerate(days, 1):
        if doy <= d:
            return (m, doy)
        doy -= d

def spanned_weeks(start_day, n_days):
    if n_days <= 0:
        return 0
    return (start_day + n_days + 6) // 7

def interval_overlap_days(s1, e1, s2, e2):
    if s1 > e1 or s2 > e2:
        return 0
    return max(0, min(e1, e2) - max(s1, s2) + 1)

def month_to_quarter(month):
    if not isinstance(month, int) or isinstance(month, bool) or not (1 <= month <= 12):
        return None
    return (month - 1) // 3 + 1

def average_word_length(text):
    words = text.split()
    if not words:
        return 0.0
    return float(sum(len(w) for w in words) / len(words))

def most_frequent_char(text):
    cleaned = text.replace(' ', '')
    if not cleaned:
        return None
    return max(cleaned, key=lambda c: cleaned.count(c))

def words_at_least_n(text, n):
    words = text.lower().split()
    if n <= 0:
        return sorted(set(words))
    return sorted({w for w in words if words.count(w) >= n})

def vowel_to_letter_ratio(text):
    letters = [c.lower() for c in text if c.isalpha()]
    if not letters:
        return 0.0
    vowels = sum(1 for c in letters if c in 'aeiou')
    return float(vowels / len(letters))

def longest_word_last(text):
    words = text.split()
    if not words:
        return ''
    res = words[0]
    for w in words[1:]:
        if len(w) >= len(res):
            res = w
    return res

def count_non_overlapping(text, sub):
    if not text or not sub:
        return 0
    return text.count(sub)

def min_max_word_length(text):
    lengths = [len(w) for w in text.split()]
    if not lengths:
        return (0, 0)
    return (min(lengths), max(lengths))

def median_word_length(text):
    lengths = sorted(len(w) for w in text.split())
    n = len(lengths)
    if n == 0:
        return 0.0
    mid = n // 2
    return float(lengths[mid] if n % 2 == 1 else (lengths[mid - 1] + lengths[mid]) / 2)

def type_token_ratio(text):
    words = text.lower().split()
    if not words:
        return 0.0
    return float(len(set(words)) / len(words))

def top_k_chars(text, k):
    if k <= 0 or not text:
        return []
    unique_chars = set(text)
    sorted_chars = sorted(unique_chars, key=lambda c: (-text.count(c), c))
    return sorted_chars[:k]

def max_sum_row_index(matrix):
    if not matrix or not matrix[0]:
        return None
    return max(range(len(matrix)), key=lambda i: (sum(matrix[i]), i))

def extract_border_clockwise(matrix):
    if not matrix or not matrix[0]:
        return []
    r, c = len(matrix), len(matrix[0])
    if r == 1:
        return list(matrix[0])
    if c == 1:
        return [row[0] for row in matrix]
    return matrix[0] + [matrix[i][-1] for i in range(1, r - 1)] + matrix[-1][::-1] + [matrix[i][0] for i in range(r - 2, 0, -1)]

def find_saddle_points(matrix):
    if not matrix or not matrix[0]:
        return []
    row_mins = [min(r) for r in matrix]
    col_maxs = [max(c) for c in zip(*matrix)]
    return [(r, c) for r in range(len(matrix)) for c in range(len(matrix[0])) if matrix[r][c] == row_mins[r] == col_maxs[c]]

def sum_matrix_diagonals(matrix):
    if not matrix or not matrix[0]:
        return 0
    n = len(matrix)
    total = sum(matrix[i][i] + matrix[i][n - 1 - i] for i in range(n))
    return total - (matrix[n // 2][n // 2] if n % 2 == 1 else 0)

def transpose_matrix(matrix):
    if not matrix or not matrix[0]:
        return []
    return [list(col) for col in zip(*matrix)]

def common_row_elements(matrix):
    if not matrix or not matrix[0]:
        return []
    return sorted(set.intersection(*(set(row) for row in matrix)))

def count_strict_local_maxima(matrix):
    if not matrix or not matrix[0]:
        return 0
    r, c = len(matrix), len(matrix[0])
    return sum(all(matrix[i][j] > matrix[ni][nj] for ni, nj in ((i-1, j), (i+1, j), (i, j-1), (i, j+1)) if 0 <= ni < r and 0 <= nj < c) for i in range(r) for j in range(c))

def is_toeplitz_matrix(matrix):
    if not matrix or not matrix[0]:
        return True
    return all(matrix[r][c] == matrix[r - 1][c - 1] for r in range(1, len(matrix)) for c in range(1, len(matrix[0])))

def column_averages(matrix):
    if not matrix or not matrix[0]:
        return ()
    return tuple(round(sum(col) / len(matrix), 2) for col in zip(*matrix))

def most_frequent_letter(s: str):
    letters = [c.lower() for c in s if c.isalpha()]
    if not letters:
        return None
    counts = {c: letters.count(c) for c in set(letters)}
    return min(counts.keys(), key=lambda c: (-counts[c], c))

def unique_vowels(s: str) -> tuple:
    vowels = set('aeiou')
    return tuple(sorted(vowels.intersection(s.lower())))

def uppercase_ratio(s: str):
    alphas = [c for c in s if c.isalpha()]
    if not alphas:
        return None
    return float(sum(1 for c in alphas if c.isupper()) / len(alphas))

def chars_with_exact_count(s: str, k: int) -> list:
    if k <= 0:
        return []
    seen = []
    for c in s:
        if c not in seen and s.count(c) == k:
            seen.append(c)
    return seen

def words_by_length(s: str) -> dict:
    words = set(w.lower() for w in s.split())
    lengths = sorted(set(len(w) for w in words))
    return {l: sorted(w for w in words if len(w) == l) for l in lengths}

def most_frequent_first(lst):
    if not lst:
        return None
    counts = {}
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
    return max(counts, key=counts.get)

def rotate_right(lst, k):
    if not lst:
        return []
    k = k % len(lst)
    return lst[-k:] + lst[:-k] if k else lst[:]

def unique_pairs_sum(nums, target):
    seen = set()
    pairs = set()
    for x in nums:
        if target - x in seen:
            pairs.add((min(x, target - x), max(x, target - x)))
        seen.add(x)
    return sorted(pairs)

def interleave_lists(a, b):
    res = []
    for x, y in zip(a, b):
        res.extend([x, y])
    n = min(len(a), len(b))
    return res + a[n:] + b[n:]

def trimmed_mean_strict(nums):
    if not nums:
        return None
    mn, mx = min(nums), max(nums)
    mid = [x for x in nums if mn < x < mx]
    return sum(mid) / len(mid) if mid else None

def binomial_coeff(n, k):
    if k == 0:
        return 1
    if n < 0 or k < 0 or k > n:
        return 0
    res = 1
    for i in range(min(k, n - k)):
        res = res * (n - i) // (i + 1)
    return res

from itertools import combinations
def unique_combinations(lst, k):
    if k < 0 or k > len(lst):
        return []
    return sorted(set(combinations(sorted(lst), k)))

def count_derangements(n):
    if n < 0:
        return None
    if n == 0:
        return 1
    a, b = 1, 0
    for i in range(2, n + 1):
        a, b = b, (i - 1) * (a + b)
    return b

def bounded_partitions(n, k, max_val=None):
    if max_val is None: max_val = n
    if n == 0: return [()] if k >= 0 else []
    if n < 0 or k <= 0: return []
    res = []
    for i in range(1, min(n, max_val) + 1):
        for p in bounded_partitions(n - i, k - 1, i):
            res.append((i,) + p)
    return sorted(res)

from itertools import permutations
def kth_permutation(lst, k):
    if not lst or k < 0:
        return None
    perms = sorted(set(permutations(lst)))
    return perms[k] if k < len(perms) else None

from itertools import combinations
def unique_pair_sums(lst, target):
    pairs = set()
    for a, b in combinations(sorted(lst), 2):
        if a + b == target:
            pairs.add((a, b))
    return sorted(pairs)

def stirling_second(n, k):
    if n < 0 or k < 0 or k > n:
        return 0
    if n == 0 and k == 0:
        return 1
    if k == 0:
        return 0
    return k * stirling_second(n - 1, k) + stirling_second(n - 1, k - 1)

def intersect_intervals(intervals):
    if not intervals:
        return None
    low = max(i[0] for i in intervals)
    high = min(i[1] for i in intervals)
    return (low, high) if low <= high else None

def max_overlap_point(intervals):
    events = []
    for s, e in intervals:
        events.extend([(s, 0, 1), (e, 1, -1)])
    cur = best_c = 0
    best_p = None
    for p, _, d in sorted(events):
        cur += d
        if cur > best_c:
            best_c, best_p = cur, p
    return best_p

def clamp_intervals(intervals, low, high):
    res = []
    for s, e in intervals:
        if s <= high and e >= low:
            res.append((max(s, low), min(e, high)))
    return res

def first_exceeding_prefix(nums, target):
    curr = 0
    for i, x in enumerate(nums):
        curr += x
        if curr > target:
            return i
    return -1

def last_max_prefix_index(nums):
    if not nums:
        return None
    curr = 0
    max_s = float('-inf')
    idx = 0
    for i, x in enumerate(nums):
        curr += x
        if curr >= max_s:
            max_s = curr
            idx = i
    return idx

def count_negative_prefixes(nums):
    curr = 0
    count = 0
    for x in nums:
        curr += x
        if curr < 0:
            count += 1
    return count

def first_balance_index(nums):
    total = sum(nums)
    curr = 0
    for i, x in enumerate(nums):
        curr += x
        if curr == total - curr:
            return i
    return -1

def unique_sorted_prefix_sums(nums):
    curr = 0
    seen = set()
    for x in nums:
        curr += x
        seen.add(curr)
    return tuple(sorted(seen))

def first_duplicate_prefix_sum(nums):
    seen = {0}
    curr = 0
    for x in nums:
        curr += x
        if curr in seen:
