    if s[0] <= 0 or s[0] + s[1] <= s[2]:
        return 'invalid'
    if s[0] == s[2]:
        return 'equilateral'
    return 'isosceles' if s[0] == s[1] or s[1] == s[2] else 'scalene'

def unique_two_sum(nums, k):
