    l, r, res = 0, len(nums) - 1, []
    while l < r:
        s = nums[l] + nums[r]
        if s == k:
            if not res or res[-1] != (nums[l], nums[r]):
                res.append((nums[l], nums[r]))
            l, r = l + 1, r - 1
        elif s < k: l += 1
        else: r -= 1
    return res

