    while l <= r:
        lv, rv = nums[l] ** 2, nums[r] ** 2
        val = lv if lv > rv else rv
        if lv > rv: l += 1
        else: r -= 1
        if not res or res[-1] != val:
            res.append(val)
    return res[::-1]

def move_zeros_front(nums):
