import re
def parse_polynomial(s):
    res = {}
    for m in re.finditer(r'([+-]?\d*)(x(?:\^(\d+))?)?', s.replace(' ', '')):
        if not m.group(0): continue
        c, x, p = m.groups()
        coeff = int(c) if c not in ('', '+', '-') else (1 if c != '-' else -1)
        exp = int(p) if p else (1 if x else 0)
        res[exp] = res.get(exp, 0) + coeff
    return {k: v for k, v in res.items() if v != 0}

def parse_literal_list(s):
    inner = s.strip()[1:-1].strip()
    if not inner: return []
    res = []
    for t in [x.strip() for x in inner.split(',')]:
        if t.lower() in ('true', 'false'): res.append(t.lower() == 'true')
        else:
            try: res.append(int(t))
            except ValueError:
                try: res.append(float(t))
                except ValueError: res.append(t)
    return res

def seconds_to_dhms(total_seconds):
