def parse_poly(s):
    import re
    res = {}
    for m in re.finditer(r'([+-]?\s*\d*)(x(?:\^(\d+))?)?', s.replace(' ', '')):
        if not m.group(0):
            continue
        c_str, x_part, exp_str = m.groups()
        c = int(c_str) if c_str not in ('', '+', '-') else (1 if c_str != '-' else -1)
        exp = int(exp_str) if exp_str is not None else (1 if x_part else 0)
