def line_from_points(p1, p2):
    if p1 == p2:
        return None
    a, b = p1[1] - p2[1], p2[0] - p1[0]
    c = -a * p1[0] - b * p1[1]
    g = math.gcd(a, math.gcd(b, c))
    a, b, c = a // g, b // g, c // g
    return (-a, -b, -c) if (a, b) < (0, 0) else (a, b, c)

