    while r < len(nums):
        if l == r or nums[r] - nums[l] < k: r += 1
        elif nums[r] - nums[l] > k: l += 1
        else:
            res.update((nums[l], nums[r]))
            l += 1
    return sorted(res)

def get_powers_of_two(nums):
    res = {x for x in nums if x > 0 and (x & (x - 1)) == 0}
    return tuple(sorted(res, reverse=True))

def invert_significant_bits(n):
    if n < 0:
        return None
    if n == 0:
        return 1
    return n ^ ((1 << n.bit_length()) - 1)

def highest_set_bit_index(n):
    if n < 0:
        return None
    return n.bit_length() - 1

def find_single_odd_occurrence(nums):
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) ^ 1
    odds = [k for k, v in counts.items() if v == 1]
    return odds[0] if len(odds) == 1 else None

def list_bitwise_and(nums):
    if not nums:
        return None
    res = nums[0]
    for x in nums[1:]:
        res &= x
    return res

def greedy_coin_change(coins, target):
    if target < 0:
        return None
    res = []
    for c in sorted(set(coins), reverse=True):
        if c > 0 and target >= c:
            count, target = divmod(target, c)
            res.extend([c] * count)
    return res if target == 0 else None

def min_max_pairs(nums):
    s = sorted(nums)
    n = len(s)
    return sorted((s[i], s[n - 1 - i]) for i in range(n // 2))

def max_k_product(nums, k):
    if k <= 0 or k > len(nums):
        return None
    s, p = sorted(nums), 1
    if s[-1] <= 0 and k % 2 == 1:
        for x in s[-k:]: p *= x
        return p
    l, r = 0, len(s) - 1
    if k % 2 == 1:
        p, r, k = s[r], r - 1, k - 1
    for _ in range(k // 2):
        if s[l] * s[l+1] > s[r-1] * s[r]: p, l = p * s[l] * s[l+1], l + 2
        else: p, r = p * s[r-1] * s[r], r - 2
    return p

def next_fit_bins(items, C):
    res = []
    for x in items:
        if x <= 0 or x > C:
            return None
        if not res or sum(res[-1]) + x > C:
            res.append([x])
        else:
            res[-1].append(x)
    return res

def max_sum_after_negations(nums, k):
    s = sorted(nums)
    for i in range(len(s)):
        if k > 0 and s[i] < 0:
            s[i], k = -s[i], k - 1
    return sum(s) - (2 * min(s) if s and k % 2 == 1 else 0)

def remove_k_digits(num, k):
    st = []
    for d in num:
        while k > 0 and st and st[-1] > d:
            st.pop()
            k -= 1
        st.append(d)
    res = ''.join(st[:max(0, len(st) - k)]).lstrip('0')
    return res if res else '0'

def match_demands(demands, capacities):
    d, c = sorted(demands), sorted(capacities)
    i = j = 0
    while i < len(d) and j < len(c):
        if c[j] >= d[i]:
            i += 1
        j += 1
    return i

def fractional_knapsack(items, W):
    if W <= 0:
        return 0.0
    total = 0.0
    for v, w in sorted((x for x in items if x[0] > 0), key=lambda x: x[0] / x[1], reverse=True):
        take = min(W, w)
        total += take * (v / w)
        W -= take
    return round(float(total), 2)

def day_to_week_day(day):
    q, r = divmod(day - 1, 7)
    return (q + 1, r + 1)

def shift_month(month, delta):
    q, r = divmod(month - 1 + delta, 12)
    return (q, r + 1)

def most_frequent_weekdays(offsets):
    if not offsets:
        return []
    counts = [0] * 7
    for x in offsets:
        counts[x % 7] += 1
    m = max(counts)
    return [i for i, c in enumerate(counts) if c == m]

def normalize_duration(duration):
    d, h, m, s = duration
    m, s = divmod(m * 60 + s, 60)
    h, m = divmod(h * 60 + m, 60)
    d, h = divmod(d * 24 + h, 24)
    return (d, h, m, s)

def days_until_next_weekday(start_weekday, target_weekdays):
    if not target_weekdays:
        return None
    return min((t - start_weekday) % 7 for t in target_weekdays)

def count_workdays(start_weekday, n_days):
    if n_days <= 0:
        return 0
    weeks, rem = divmod(n_days, 7)
    extra = sum((start_weekday + i) % 7 < 5 for i in range(rem))
    return weeks * 5 + extra

def recurring_days_in_range(origin, period, start_day, end_day):
    if start_day > end_day:
        return []
    first = start_day + (origin - start_day) % period
    if first < origin:
        first = origin
    return list(range(first, end_day + 1, period))
